        #region TrnExcelImport_Load

        private void TrnExcelImport_Load(object sender, EventArgs e)
        {
            int h = Screen.PrimaryScreen.WorkingArea.Height;
            int w = Screen.PrimaryScreen.WorkingArea.Width;
            this.ClientSize = new Size(w, h);
            //////
            GC.Collect();
            //
            //Added by Indrajit on 23-02-2013
            tmrLoginRefresh.Interval = (int)TDSMAN.Classes.TDSMAN.T_pLockInterval * 60000;
            tmrLoginRefresh.Start();
            //-----
            if (dmlService.J_IsDatabaseObjectExist("MST_ASSESSMENT", "FLAG_26_27_ONWARDS") == true)
            {
                //
                strSQL = "UPDATE MST_ASSESSMENT SET FLAG_26_27_ONWARDS = 1 WHERE ASST_ID >= 22";
                dmlService.J_ExecSql(strSQL);
                //
                strSQL = "UPDATE MST_ASSESSMENT SET SD_US_16_IA_LIMIT_NEW_REGIME = 75000 WHERE ASST_ID = 22";
                dmlService.J_ExecSql(strSQL);
            }
            //
            if (CSVImport == 0)
            {
                lblTitle.Text = "Excel Validate";
                BtnSave.Text = "&Validate Excel file";
                //
                cmbFinancialYear.Select();
                //-- FINANCIAL YEAR
                //-----------
                strSQL = " SELECT ASST_ID," +
                    "             FA_YEAR " +
                    "      FROM   MST_ASSESSMENT " +
                    "      WHERE  VISIBILITY_FLAG = 0 " +
                    "      ORDER BY ASST_ID DESC";
                if (dmlService.J_PopulateComboBox(strSQL, ref cmbFinancialYear, 1, J_ComboBoxSelectedIndex.YES) == false) return;
                //-----------
                //-- QUARTER
                //-----------
                string[] strQtr = { T_Qtr.Q1, T_Qtr.Q2, T_Qtr.Q3, T_Qtr.Q4 };
                dmlService.J_PopulateComboBox(strQtr, ref cmbQuarter, 1);
                //## SELECT THE CURRENT QUARTER
                if(cmnService.J_ReturnInt32Value(cmnService.J_Mid(dtService.J_ConvertToIntYYYYMMDD(System.DateTime.Now.ToString()).ToString(), 4, 2)) >= 4 
                    && cmnService.J_ReturnInt32Value(cmnService.J_Mid(dtService.J_ConvertToIntYYYYMMDD(System.DateTime.Now.ToString()).ToString(), 4, 2)) <= 6)                
                    cmbQuarter.Text = T_Qtr.Q1.ToString();
                else if (cmnService.J_ReturnInt32Value(cmnService.J_Mid(dtService.J_ConvertToIntYYYYMMDD(System.DateTime.Now.ToString()).ToString(), 4, 2)) >= 7
                    && cmnService.J_ReturnInt32Value(cmnService.J_Mid(dtService.J_ConvertToIntYYYYMMDD(System.DateTime.Now.ToString()).ToString(), 4, 2)) <= 9)
                    cmbQuarter.Text = T_Qtr.Q2.ToString();
                else if (cmnService.J_ReturnInt32Value(cmnService.J_Mid(dtService.J_ConvertToIntYYYYMMDD(System.DateTime.Now.ToString()).ToString(), 4, 2)) >= 10
                    && cmnService.J_ReturnInt32Value(cmnService.J_Mid(dtService.J_ConvertToIntYYYYMMDD(System.DateTime.Now.ToString()).ToString(), 4, 2)) <= 12)
                    cmbQuarter.Text = T_Qtr.Q3.ToString();
                else
                    cmbQuarter.Text = T_Qtr.Q4.ToString();
                //##
                //--
                strSQL = " SELECT COMPANY_ID," +
                    "             COMPANY_NAME + ' [' + TAN_NO + ']'" +
                    "      FROM   MST_COMPANY " +
                    "      WHERE  INACTIVE_FLAG = 0 " +
                    "      ORDER BY COMPANY_NAME";
                if (dmlService.J_PopulateComboBox(strSQL, ref cmbCompany) == false) return;
                //
                BtnSave.Tag = T_SaveTag.VALIDATE;
                //-- 
                if (TDSMAN.Classes.TDSMAN.T_EnableDeducteeFirst == true)
                    grpEnterDeducteeDetailsOnly.Visible = true;
                else
                    grpEnterDeducteeDetailsOnly.Visible = false;
                //
                blnOpenTabPage = true;
                tbcExcelImport.SelectTab(tbpValidateExcelFile);
            }
            else
            {
                lblTitle.Text = "CSV Validate";
                BtnSave.Text = "&Validate CSV file";
                //
                cmbCSVFinancialYear.Select();
                //-- FINANCIAL YEAR
                //-----------
                strSQL = " SELECT ASST_ID," +
                    "             FA_YEAR " +
                    "      FROM   MST_ASSESSMENT " +
                    "      WHERE  VISIBILITY_FLAG = 0 " +
                    "      ORDER BY ASST_ID DESC";
                if (dmlService.J_PopulateComboBox(strSQL, ref cmbCSVFinancialYear, 1, J_ComboBoxSelectedIndex.YES) == false) return;
                //-----------
                //-- QUARTER
                //-----------
                string[] strQtr = { T_Qtr.Q1, T_Qtr.Q2, T_Qtr.Q3, T_Qtr.Q4 };
                dmlService.J_PopulateComboBox(strQtr, ref cmbCSVQtr, 1);
                //## SELECT THE CURRENT QUARTER
                if (cmnService.J_ReturnInt32Value(cmnService.J_Mid(dtService.J_ConvertToIntYYYYMMDD(System.DateTime.Now.ToString()).ToString(), 4, 2)) >= 4
                    && cmnService.J_ReturnInt32Value(cmnService.J_Mid(dtService.J_ConvertToIntYYYYMMDD(System.DateTime.Now.ToString()).ToString(), 4, 2)) <= 6)
                    cmbCSVQtr.Text = T_Qtr.Q1.ToString();
                else if (cmnService.J_ReturnInt32Value(cmnService.J_Mid(dtService.J_ConvertToIntYYYYMMDD(System.DateTime.Now.ToString()).ToString(), 4, 2)) >= 7
                    && cmnService.J_ReturnInt32Value(cmnService.J_Mid(dtService.J_ConvertToIntYYYYMMDD(System.DateTime.Now.ToString()).ToString(), 4, 2)) <= 9)
                    cmbCSVQtr.Text = T_Qtr.Q2.ToString();
                else if (cmnService.J_ReturnInt32Value(cmnService.J_Mid(dtService.J_ConvertToIntYYYYMMDD(System.DateTime.Now.ToString()).ToString(), 4, 2)) >= 10
                    && cmnService.J_ReturnInt32Value(cmnService.J_Mid(dtService.J_ConvertToIntYYYYMMDD(System.DateTime.Now.ToString()).ToString(), 4, 2)) <= 12)
                    cmbCSVQtr.Text = T_Qtr.Q3.ToString();
                else
                    cmbCSVQtr.Text = T_Qtr.Q4.ToString();
                //##
                //--
                strSQL = " SELECT COMPANY_ID," +
                    "             COMPANY_NAME + ' [' + TAN_NO + ']'" +
                    "      FROM   MST_COMPANY " +
                    "      WHERE  INACTIVE_FLAG = 0 " +
                    "      ORDER BY COMPANY_NAME";
                if (dmlService.J_PopulateComboBox(strSQL, ref cmbCSVCompany) == false) return;
                //
                BtnSave.Tag = T_SaveTag.VALIDATE;
                //-- 
                if (TDSMAN.Classes.TDSMAN.T_EnableDeducteeFirst == true)
                    grpEnterDeducteeDetailsOnly.Visible = true;
                else
                    grpEnterDeducteeDetailsOnly.Visible = false;
                //
                blnOpenTabPage = true;
                tbcExcelImport.SelectTab(tbpValidateCSVFile);
            }
                //strMessagePANVerification = "PANs to be verified exceeds " + lngMAXLineNumbersPANVerificationMessage.ToString() + " nos. As this will take time, it is recommended to exit\n from here and go ahead with the ‘Data Import’.\n Later use the ‘PAN Name Extractor’ from the ‘Utilities’ menu for verifying the PANs.\n" +
                //                            "Click ‘No’ to exit PAN verification.\nBy clicking ‘Yes’, the verification will start.";
                strMessagePANVerification = "PANs to be verified exceeds " + lngMAXLineNumbersPANVerificationMessage.ToString() + " nos.\n\nIt is recommended to use the ‘PAN Name Extractor’ from the ‘Utilities’ menu for verifying the PANs.\n" +
                                            "\nTo exit, click ‘No’ or to continue with Verification click ‘Yes’.";

            
        }

        #endregion

        #region btnSelectExcelPath_Click
        private void btnSelectExcelPath_Click(object sender, EventArgs e)
        {
            if (TDSMAN.Classes.TDSMAN.T_pEditionType == T_EDITION_TYPE.ENTERPRISE_EDITION || TDSMAN.Classes.TDSMAN.T_pEditionType == T_EDITION_TYPE.ENTERPRISE_LITE_EDITION || TDSMAN.Classes.TDSMAN.T_pEditionType == T_EDITION_TYPE.ENTERPRISE_ULTIMATE_EDITION)
                strFVUPath = cmnService.J_OpenFileDialog("Excel File | *.xlsx", "Excel File | *.xlsx", "Choose the Excel File to import");
            else
                strFVUPath = cmnService.J_OpenFileDialog("Excel File | *.xls; *.xlsx", "Excel File | *.xls; *.xlsx", "Choose the Excel File to import");
            //--
            if (strFVUPath != "")
                txtExcelPath.Text = strFVUPath;            
        }
        #endregion

        #region BtnExit_Click
        private void BtnExit_Click(object sender, System.EventArgs e)
        {
            GC.Collect();
            //
            if (BtnExit.Text == "Back")
            {
                dgcViewDeductee.Visible = false;
                dgcViewChallan.Visible = true;
                //--
                LoadChallanGrid(Convert.ToInt32(intFinancialYearId));
                BtnExit.Text = "Exit";
            }
            else
            {
                dmlService.Dispose();
                this.Close();
                this.Dispose();
            }
        }
        #endregion

        #region BtnSave_Click
        private void BtnSave_Click(object sender, EventArgs e)
        {
            try
            {
                //-- Added By Abhishek Dey On 01/11/2019 --
                #region IS COMPANY ACCESSABLE FOR CLIENT
                if (TDSMAN.Classes.TDSMAN.T_ClientServerMachine == T_CLIENT_SERVER_MACHINE.CLIENT_MACHINE)
                {
                    if (dmlService.J_IsDatabaseObjectExist("TRN_TAN_USER") == true)
                    {
                        if (tbcExcelImport.SelectedTab == tbpValidateExcelFile)
                        {
                            if (TdsMan.IsCompanyAccessible(Convert.ToInt64(Support.GetItemData(cmbCompany, cmbCompany.SelectedIndex)), TDSMAN.Classes.TDSMAN.T_MACHINE_ID) == false)
                            {
                                cmnService.J_UserMessage("You are not authorised to proceed.");
                                BtnExit.Select();
                                return;
                            }
                        }
                        else if (tbcExcelImport.SelectedTab == tbpValidateCSVFile)
                        {
                            if (TdsMan.IsCompanyAccessible(Convert.ToInt64(Support.GetItemData(cmbCSVCompany, cmbCSVCompany.SelectedIndex)), TDSMAN.Classes.TDSMAN.T_MACHINE_ID) == false)
                            {
                                cmnService.J_UserMessage("You are not authorised to proceed.");
                                BtnExit.Select();
                                return;
                            }

                        }

                        //if (Convert.ToInt32(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(*) FROM TRN_TAN_USER WHERE SETUP_ID = " + TDSMAN.Classes.TDSMAN.T_MACHINE_ID + " AND COMPANY_ID = " + )) > 0)

                    }
                }
