                                return;
                        }
                        else
                        {
                            if (cmnService.J_UserMessage(strMessage + "\n based on \n " +
                                "FINANCIAL YEAR \t: " + strFinancialYear + " \n " +
                                "QUARTER \t: " + strQtr + " \n " +
                                "FORM NO. \t: " + lblFormNo.Text + " \n " +
                                "COMPANY \t: " + strCompany + " \n \n" +
                                "Proceed??", MessageBoxButtons.YesNo) == DialogResult.No)
                                return;
                        }
                        //--
                        prgImportBar.Value = 0;
                        //--
                        this.Cursor = Cursors.WaitCursor;
                        //--                
                        prgImportBar.Value = prgImportBar.Value + 5;
                        this.Refresh();
                        //--
                        lngBasicInfoID = TdsMan.T_ReturnBasicInfoId(dmlService.J_pCommand, intFinancialYearId,
                            strQtr,
                            intCompanyId,
                            strFormNo);
                        //--
                        if (lngBasicInfoID == 0)
                        {
                            if (TdsMan.T_GenerateBasicInfoId(dmlService.J_pCommand, intFinancialYearId,
                                                            strQtr,
                                                            intCompanyId,
                                                            strFormNo) == true)
                            {
                                lngBasicInfoID = TdsMan.T_ReturnBasicInfoId(dmlService.J_pCommand, intFinancialYearId,
                                                    strQtr,
                                                    intCompanyId,
                                                    strFormNo);
                                InsertCompanyBasicInfo(intCompanyId, lngBasicInfoID);
                            }
                        }
                        //--
                        TdsMan.SHRINK_DATABASE();
                        //--###########################
                        if (TdsMan.LimitEditions(lngBasicInfoID, Incremental, false, false, "TRN_DEDUCTEE_DETAILS", "BASIC_INFO_ID", TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS, "") == false)
                        //if (TdsMan.LimitEditions(lngBasicInfoID, Incremental, false, false, TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS, "") == false)
                        {
                            prgImportBar.Value = 0;
                            this.Refresh();
                            this.Cursor = Cursors.Default;
                            BtnSave.Enabled = false;
                            return;
                        }
                        //--###########################
                        //--
                        //Added by Shrey Kejriwal on 20/01/2012
                        strSQL = "UPDATE TRN_BASIC_INFO SET NIL_RETURN = 0 WHERE BASIC_INFO_ID = " + lngBasicInfoID;
                        dmlService.J_ExecSql(strSQL);
                        //
                        if (NewImport == true)
                        {
                            if (TdsMan.T_DeleteDeducteeDetails(lngBasicInfoID) == false)
                            {
                                cmnService.J_UserMessage("Import failed", MessageBoxIcon.Error);
                                this.Cursor = Cursors.Default;
                                return;
                            }
                            //
                            prgImportBar.Value = prgImportBar.Value + 5;
                            this.Refresh();
                            //
                            if (chkEnterDeducteeDetailsOnly.Checked == false)
                            {
                                if (TdsMan.T_DeleteChallanDetails(lngBasicInfoID) == false)
                                {
                                    cmnService.J_UserMessage("Import failed", MessageBoxIcon.Error);
                                    this.Cursor = Cursors.Default;
                                    return;
                                }
                            }
                            //
                            prgImportBar.Value = prgImportBar.Value + 5;
                            this.Refresh();
                            //
                        }
                        //--

                        //--
                        if (TdsMan.T_DeleteReceiptNo(lngBasicInfoID) == false)
                        {
                            cmnService.J_UserMessage("Import failed", MessageBoxIcon.Error);
                            this.Cursor = Cursors.Default;
                            return;
                        }
                        //
                        prgImportBar.Value = prgImportBar.Value + 5;
                        this.Refresh();
                        //--
                        if (chkEnterDeducteeDetailsOnly.Checked == false)
                        {
                            if (INSERT_CHALLAN_DATA(lngBasicInfoID, intFinancialYearId) == false)
                            {
                                cmnService.J_UserMessage("Import failed", MessageBoxIcon.Error);
                                this.Cursor = Cursors.Default;
                                return;
                            }
                        }
                        //
                        prgImportBar.Value = prgImportBar.Value + 5;
                        this.Refresh();
                        //--                
                        if (INSERT_MASTER_DATA(strFormNo, intCompanyId) == false)
                        {
                            cmnService.J_UserMessage("Import failed", MessageBoxIcon.Error);
                            this.Cursor = Cursors.Default;
                            return;
                        }
                        this.Refresh();
                        //--
                        if (INSERT_DEDUCTEE_DATA(lngBasicInfoID, intFinancialYearId, strFormNo, blnDeducteeDetailsOnly) == false)
                        {
                            cmnService.J_UserMessage("Import failed", MessageBoxIcon.Error);
                            this.Cursor = Cursors.Default;
                            return;
                        }
                        this.Refresh();
                        //
                        #endregion
                    }
                    //--
                    if (DROP_TEMP_TABLES() == false)
                    {
                        cmnService.J_UserMessage("Import failed", MessageBoxIcon.Error);
                        this.Cursor = Cursors.Default;
                        return;
                    }
                    this.Refresh();
                    //
                    if (strFormNo == T_FormNo.F24QSalaryDetails)
                    {
                        for (int i = prgSDBar.Minimum; i <= prgSDBar.Maximum; i++)
                        {
                            prgSDBar.PerformStep();
                        }
                    }
                    else
                    {
                        for (int i = prgImportBar.Minimum; i <= prgImportBar.Maximum; i++)
                        {
                            prgImportBar.PerformStep();
                        }
                    }
                    //
                    BtnSave.Enabled = false;
                    //
                    this.Cursor = Cursors.Default;
                    //--
                    BtnExit.Text = "E&xit";
                    //---------------------------------------------------------
                    //---------------------------------------------------------
                    //ADDED BY DHRUB ON 07/01/2014 FOR BOOKMARK
                    //---------------------------------------------------------
                    if (TDSMAN.Classes.TDSMAN.T_pBookMarkOption == true)
                    {
                        //strQuery = @"FORM_NAME= '" + FormNo + "' ";
                        //-- 2014/11/14
                        strQuery = @" FORM_NAME= '" + strFormNo + "' AND SETUPID = " + TDSMAN.Classes.TDSMAN.T_MACHINE_ID;
                        //
                        string strBookmarkFormNo = "";
                        if (strFormNo == T_FormNo.F24QSalaryDetails
                            || strFormNo == T_FormNo.F24QForm16SalaryDetails)
                            strBookmarkFormNo = cmnService.J_Left(strFormNo, 4).Trim();
                        else
                            strBookmarkFormNo = strFormNo;
                        //
                        if (dmlService.J_IsRecordExist("MST_BOOKMARK_DETAIL", strQuery) == true)
                        {
                            //Inserting the Form BookMarkDetail
                            intAsstId = TdsMan.T_GetBookMarkDetail(T_TransactionMode.UPDATE.ToString(),
                                                                Convert.ToInt32(intFinancialYearId),
                                                                strQtr,
                                                                strBookmarkFormNo,
                                                                Convert.ToInt32(intCompanyId),
                                                                TDSMAN.Classes.TDSMAN.T_MACHINE_ID,
                                                                out strQuarter,
                                                                out strCompanyName
                                                               );
                        }
                        else
                        {
                            //Inserting the Form BookMarkDetail
                            intAsstId = TdsMan.T_GetBookMarkDetail(T_TransactionMode.INSERT.ToString(),
                                                                Convert.ToInt32(intFinancialYearId),
                                                                strQtr,
                                                                strBookmarkFormNo,
                                                                Convert.ToInt32(intCompanyId),
                                                                TDSMAN.Classes.TDSMAN.T_MACHINE_ID,
                                                                out strQuarter,
                                                                out strCompanyName
                                                               );
                        }
                    }
                    //---------------------------------------------------------
                    //---------------------------------------------------------
                    cmnService.J_UserMessage("Import completed", MessageBoxIcon.Information);
                    prgImportBar.Value = 0;
                    prgSDBar.Value = 0;
                    //
                    if (lblFormNo.Tag == "")
                        TDSMAN.Classes.TDSMAN.T_pTabFormCaption = lblSDFormNo.Text;
                    else
                        TDSMAN.Classes.TDSMAN.T_pTabFormCaption = lblFormNo.Tag.ToString();
                    //
                    this.Close();
                    this.Dispose();
                    //--
                    //Do you want to check the data imported?
                    if (cmnService.J_UserMessage("Do you want to go to Form " + TDSMAN.Classes.TDSMAN.T_pTabFormCaption + " to view the data imported??", MessageBoxButtons.YesNo, MessageBoxIcon.Question) == DialogResult.Yes)
                    {
                        if (cmnService.J_ReturnInt32Value(lblFinancialYearId.Text) < T_FinancialYearID.F2026_27ID)
                        {
                            if (chkEnterDeducteeDetailsOnly.Checked == true)
                            {
                                TdsMan.CloseChildForm(new TrnRegularReturn(T_DEDUCTEE_FIRST_MODULES.DEDUCTEE), J_Var.frmMain);
                                //--
                                cmnService.J_ShowChildForm(new TrnRegularReturn(T_DEDUCTEE_FIRST_MODULES.DEDUCTEE), J_Var.frmMain, "Form  " + lblFormNo.Tag + " - Deductee entry without Challan");
                            }
                            else
                            {
                                //
                                TdsMan.CloseChildForm(new TrnRegularReturn(0), J_Var.frmMain);
                                //
                                cmnService.J_ShowChildForm(new TrnRegularReturn(0), J_Var.frmMain, "Form " + lblFormNo.Tag);
                            }
                        }
                        else
                        {
                            if (chkEnterDeducteeDetailsOnly.Checked == true)
                            {
                                TdsMan.CloseChildForm(new TrnRegularReturn_26_27(T_DEDUCTEE_FIRST_MODULES.DEDUCTEE), J_Var.frmMain);
                                //--
                                cmnService.J_ShowChildForm(new TrnRegularReturn_26_27(T_DEDUCTEE_FIRST_MODULES.DEDUCTEE), J_Var.frmMain, "Form  " + lblFormNo.Tag + " - Deductee entry without Challan");
                            }
                            else
                            {
                                //
                                TdsMan.CloseChildForm(new TrnRegularReturn_26_27(0), J_Var.frmMain);
                                //
                                cmnService.J_ShowChildForm(new TrnRegularReturn_26_27(0), J_Var.frmMain, "Form " + lblFormNo.Tag);
                            }
                        }
                    }
                    //--
                    //
                    #endregion
                }
                //------------------------
            }
            catch (Exception err)
            {
                System.Diagnostics.StackTrace trace = new System.Diagnostics.StackTrace(err, true);
                //Console.WriteLine("Line: " + trace.GetFrame(0).GetFileLineNumber());
                cmnService.J_UserMessage(err.Message + " ## " + trace.GetFrame(0).GetFileLineNumber());
                //cmnService.J_UserMessage(err.Message);
                return;
            }
        }
        #endregion

