        #region cmbFormNo_SelectedIndexChanged
        private void cmbFormNo_SelectedIndexChanged(object sender, EventArgs e)
        {
            pctVideoDemo.Visible = false;
            //
            chkRoundOffTaxableAmount.Visible = false;
            if (cmbFormNo.Text == T_FormNo.F24QForm16SalaryDetails || cmbFormNo.Text == T_FormNo.F24QSalaryDetails || cmbFormNo.Text == T_FormNo.F24QAnnexureIII)
            {
                chkEnterDeducteeDetailsOnly.Checked = false;
                chkEnterDeducteeDetailsOnly.Enabled = false;
                //
                lblNoteAdd.Visible = false;
                //
                if (cmbFormNo.Text == T_FormNo.F24QForm16SalaryDetails)
                    pctVideoDemo.Visible = true;
                else
                    pctVideoDemo.Visible = false;
                //-- 2020/06/15
                if (cmbFormNo.Text == T_FormNo.F24QSalaryDetails && TDSMAN.Classes.TDSMAN.T_EnableRoundOffTaxableAmt == true)
                    chkRoundOffTaxableAmount.Visible = true;
                else
                    chkRoundOffTaxableAmount.Visible = false;
                //-- 2025/01/21
                lblTaxComputingMessageF24QSDExcel.Visible = true;
            }
            else
            {
                pctVideoDemo.Visible = true;
                //
                lblNoteAdd.Visible = true;
                //
                if (chkEnterDeducteeDetailsOnly.Checked != true)
                {
                    chkEnterDeducteeDetailsOnly.Checked = false;
                    chkEnterDeducteeDetailsOnly.Enabled = true;
                }
                //-- 2025/01/21
                lblTaxComputingMessageF24QSDExcel.Visible = false;
            }
        }
