        #region User Defined Functions

        #region ValidateFields
        private bool ValidateFields()
        {
            try
            {
                //int V =  FileVersionInfo.GetVersionInfo(;
                //V.ToString();
                if (lblSearchMode.Text == J_Mode.Sorting)
                {
                    //if (Convert.ToInt64(Convert.ToString(ViewGrid.CurrentRowIndex)) < 0)
                    //{
                    //    cmnService.J_UserMessage(J_Msg.DataNotFound);
                    //    if (dsetGridClone == null) return false;
                    //    dmlService.J_setGridPosition(ref ViewGrid, dsetGridClone, "EMPLOYEE_ID", lngSearchId);
                    //    return false;
                    //}
                    return true;
                }
                else if (lblSearchMode.Text == J_Mode.Searching)
                {
                    //if (grpSearch.Visible == false)
                    //{
                    //    if (Convert.ToInt64(Convert.ToString(ViewGrid.CurrentRowIndex)) < 0)
                    //    {
                    //        cmnService.J_UserMessage(J_Msg.DataNotFound);
                    //        if (dsetGridClone == null) return false;
                    //        dmlService.J_setGridPosition(ref ViewGrid, dsetGridClone, "EMPLOYEE_ID", lngSearchId);
                    //        return false;
                    //    }
                    //}
                    //else if (grpSearch.Visible == true)
                    //{
                    //    if (txtPANSearch.Text.Trim() == "" &&
                    //        txtEmployeeNameSearch.Text.Trim() == "" &&
                    //        txtCompanyNameSearch.Text.Trim() == "")
                    //    {
                    //        cmnService.J_UserMessage(J_Msg.SearchingValues);
                    //        txtPANSearch.Select();
                    //        return false;
                    //    }
                    //}
                    //return true;
                }
                else
                {
                    if (tbcExcelImport.SelectedTab == tbpValidateExcelFile)
                    {
                        //-----------------------------------------------------------------------
                        //-- FINANCILAL YEAR
                        //-----------------------------------------------------------------------
                        if (cmbFinancialYear.SelectedIndex <= 0)
                        {
                            cmnService.J_UserMessage("Financial Year - Cannot be Blank");
                            cmbFinancialYear.Select();
                            return false;
                        }
                        //-----------------------------------------------------------------------
                        //-- QTR
                        //-----------------------------------------------------------------------
                        if (cmbQuarter.SelectedIndex <= 0)
                        {
                            cmnService.J_UserMessage("Quarter - Cannot be Blank");
                            cmbQuarter.Select();
                            return false;
                        }
                        //-----------------------------------------------------------------------
                        //-- FORM NO
                        //-----------------------------------------------------------------------
                        if (cmbFormNo.SelectedIndex <= 0)
                        {
                            cmnService.J_UserMessage("Form No. - Cannot be Blank");
                            cmbFormNo.Select();
                            return false;
                        }
                        //-----------------------------------------------------------------------
                        //-- COMPANY NAME
                        //-----------------------------------------------------------------------
                        if (cmbCompany.SelectedIndex <= 0)
                        {
                            cmnService.J_UserMessage("Company - Cannot be Blank");
                            cmbCompany.Select();
                            return false;
                        }
                        //-- RESTRICT IMPORT IF DATA IS IMPORTED FROM CONSO FILE
                        //-- GET BASIC_INFO_ID
                        string strGetFormNo = "";
                        if (Support.GetItemData(cmbFinancialYear, cmbFinancialYear.SelectedIndex) >= (int)T_FinancialYearID.F2026_27ID)
                        {
                            if (cmbFormNo.Text == T_FormNo.F138_24Q + " (" + T_FormNo.F24Q + ")")
                                strGetFormNo = T_FormNo.F24Q;
                            else if (cmbFormNo.Text == T_FormNo.F140_26Q + " (" + T_FormNo.F26Q + ")")
                                strGetFormNo = T_FormNo.F26Q;
                            else if (cmbFormNo.Text == T_FormNo.F144_27Q + " (" + T_FormNo.F27Q + ")")
                                strGetFormNo = T_FormNo.F27Q;
                            else if (cmbFormNo.Text == T_FormNo.F143_27EQ + " (" + T_FormNo.F27EQ + ")")
                                strGetFormNo = T_FormNo.F27EQ;
                        }
                            else
                                strFormNo = cmbFormNo.Text;
                        //
                        long lngBasicInfoIDConso = TdsMan.T_ReturnBasicInfoId(dmlService.J_pCommand, Convert.ToInt32(Support.GetItemData(cmbFinancialYear, cmbFinancialYear.SelectedIndex)),
                                                                            cmbQuarter.Text,
                                                                            Convert.ToInt32(Support.GetItemData(cmbCompany, cmbCompany.SelectedIndex)),
                                                                            strGetFormNo);
                        if (lngBasicInfoIDConso > 0)
                        {
                            //-- CHECK WHETHER DATA IS IMPORTED OR NOT
                            strSQL = @"SELECT IMPORTED_FROM_CONSO_DATE FROM TRN_BASIC_INFO WHERE BASIC_INFO_ID = " + lngBasicInfoIDConso + " AND IMPORTED_FROM_CONSO_DATE IS NOT NULL";
                            if (Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL)) != "")
                            {
                                cmnService.J_UserMessage("This return was imported via CONSO file on " + Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL)) + " and cannot be modified.\nHowever you can re-import via CONSO File.");
                                return false;
                            } 
                        }
                        //-----------------------------------------------------------------------
                        //-- FVU FILE SELECTED
                        //-----------------------------------------------------------------------
                        if (txtExcelPath.Text.Trim() == "")
                        {
                            cmnService.J_UserMessage("Excel file not selected");
                            btnSelectExcelPath.Select();
                            return false;
                        }
                        // FILE SHOULD BE FVU
                        if (Path.GetExtension(txtExcelPath.Text).ToUpper() != ".XLS" && Path.GetExtension(txtExcelPath.Text).ToUpper() != ".XLSX")
                        {
                            cmnService.J_UserMessage("Selected file should be a Excel file");
                            btnSelectExcelPath.Select();
                            return false;
                        }
                        // FILE EXIST
                        if (cmnService.J_IsFileExist(txtExcelPath.Text) == false)
                        {
                            cmnService.J_UserMessage("Selected Excel file not found");
                            btnSelectExcelPath.Select();
                            return false;
                        }
                        // FILE OPEN
                        string strPath = txtExcelPath.Text.ToString();
                        //
                        if (TdsMan.T_isFileOpenOrReadOnly(ref strPath) == true)
                        {
                            cmnService.J_UserMessage("Selected Excel file is open");
                            btnSelectExcelPath.Select();
                            return false;
                        }
                        //--
                        #region TAN NO - COMPANY CHECK
                        if (Path.GetExtension(txtExcelPath.Text.Trim().ToLower()) == ".xls")
                            strConnectionString = "Provider=Microsoft.Jet.OLEDB.4.0;Data Source=" + txtExcelPath.Text + ";Extended Properties=\"Excel 8.0;HDR=Yes;IMEX=1\"";
                        else if (Path.GetExtension(txtExcelPath.Text.Trim().ToLower()) == ".xlsx")
                            strConnectionString = "Provider=Microsoft.ACE.OLEDB.12.0;Data Source=" + txtExcelPath.Text + ";Extended Properties=\"Excel 12.0 Xml;HDR=Yes;IMEX=1\"";
                        //
                        con = new OleDbConnection(strConnectionString);
                        //                
                        con.Open();
                        if (TdsMan.T_IsExcelDatabaseObjectExist("Company Details", null, con) == true)
                        {
                            string strImportCompanyTan = string.Empty;
                            //// READ EXCEL FILE
                            DataSet myDataSet;
                            OleDbDataAdapter myCommand;
                            //
                            //Create Dataset and fill with imformation from the Excel Spreadsheet for easier reference
                            myDataSet = new DataSet();
                            //
                            myCommand = new OleDbDataAdapter("SELECT * FROM [Company Details$]", con);
                            myCommand.Fill(myDataSet);
                            //
                            con.Close();
                            con.Dispose();
                            //
                            int i = 0;
                            foreach (DataRow myDataRow in myDataSet.Tables[0].Rows)
                            {
                                i = i + 1;
                                //Stores info in Datarow into an array
                                if (i == 2)
                                {
                                    Object[] cells = myDataRow.ItemArray;
                                    //
                                    strImportCompanyTan = Convert.ToString(cells[0]).ToUpper();
                                }

                            }
                            if (string.IsNullOrEmpty(strImportCompanyTan))
                            {
                                cmnService.J_UserMessage("In 'Company Details' sheet, the TAN is mandatory.");
                                return false;
                            }
                            //--
                            if (Convert.ToInt32(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(*) AS COUNT1 FROM MST_COMPANY WHERE TAN_NO = '" + strImportCompanyTan + "'"))) == 0)
                            {
                                cmnService.J_UserMessage("The TAN entered in the 'Company Details' sheet is not available in Company Master.");
                                return false;
                            }
                            //--
                            if (strImportCompanyTan.Equals(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT TAN_NO FROM MST_COMPANY WHERE COMPANY_ID = " + Convert.ToInt32(Support.GetItemData(cmbCompany, cmbCompany.SelectedIndex))))))
                                return true;
                            else
                            {
                                cmnService.J_UserMessage("The TAN selected and the TAN entered in the 'Company Details' sheet does not matches.");
                                return false;
                            }
                            //--
                        }
                        else
                        {
                            con.Close();
                            con.Dispose();
                        }
                        #endregion

                    }
                    else if (tbcExcelImport.SelectedTab == tbpValidateCSVFile)
                    {
                        //-----------------------------------------------------------------------
                        //-- FINANCILAL YEAR
                        //-----------------------------------------------------------------------
                        if (cmbCSVFinancialYear.SelectedIndex <= 0)
                        {
                            cmnService.J_UserMessage("Financial Year - Cannot be Blank");
                            cmbCSVFinancialYear.Select();
                            return false;
                        }
                        //-----------------------------------------------------------------------
                        //-- QTR
                        //-----------------------------------------------------------------------
                        if (cmbCSVQtr.SelectedIndex <= 0)
                        {
                            cmnService.J_UserMessage("Quarter - Cannot be Blank");
                            cmbCSVQtr.Select();
                            return false;
                        }
                        //-----------------------------------------------------------------------
                        //-- FORM NO
                        //-----------------------------------------------------------------------
                        if (cmbCSVFormNo.SelectedIndex <= 0)
                        {
                            cmnService.J_UserMessage("Form No. - Cannot be Blank");
                            cmbCSVFormNo.Select();
                            return false;
                        }
                        //-----------------------------------------------------------------------
                        //-- COMPANY NAME
                        //-----------------------------------------------------------------------
                        if (cmbCSVCompany.SelectedIndex <= 0)
                        {
                            cmnService.J_UserMessage("Company - Cannot be Blank");
                            cmbCSVCompany.Select();
                            return false;
                        }
                        //-- RESTRICT IMPORT IF DATA IS IMPORTED FROM CONSO FILE
                        //-- GET BASIC_INFO_ID
                        string strGetFormNo = "";
                        if (Support.GetItemData(cmbCSVFinancialYear, cmbCSVFinancialYear.SelectedIndex) >= (int)T_FinancialYearID.F2026_27ID)
                        {
                            if (cmbCSVFormNo.Text == T_FormNo.F138_24Q + " (" + T_FormNo.F24Q + ")")
                                strGetFormNo = T_FormNo.F24Q;
                            else if (cmbCSVFormNo.Text == T_FormNo.F140_26Q + " (" + T_FormNo.F26Q + ")")
                                strGetFormNo = T_FormNo.F26Q;
                            else if (cmbCSVFormNo.Text == T_FormNo.F144_27Q + " (" + T_FormNo.F27Q + ")")
                                strGetFormNo = T_FormNo.F27Q;
                            else if (cmbCSVFormNo.Text == T_FormNo.F143_27EQ + " (" + T_FormNo.F27EQ + ")")
                                strGetFormNo = T_FormNo.F27EQ;
                        }
                        else
                            strFormNo = cmbFormNo.Text;
                        //
                        long lngBasicInfoIDConso = TdsMan.T_ReturnBasicInfoId(dmlService.J_pCommand, Convert.ToInt32(Support.GetItemData(cmbCSVFinancialYear, cmbCSVFinancialYear.SelectedIndex)),
                                                                            cmbCSVQtr.Text,
                                                                            Convert.ToInt32(Support.GetItemData(cmbCSVCompany, cmbCSVCompany.SelectedIndex)),
                                                                            strGetFormNo);
                        if (lngBasicInfoIDConso > 0)
                        {
                            //-- CHECK WHETHER DATA IS IMPORTED OR NOT
                            strSQL = @"SELECT IMPORTED_FROM_CONSO_DATE FROM TRN_BASIC_INFO WHERE BASIC_INFO_ID = " + lngBasicInfoIDConso + " AND IMPORTED_FROM_CONSO_DATE IS NOT NULL";
                            if (Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL)) != "")
                            {
                                cmnService.J_UserMessage("This return was imported via CONSO file on " + Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL)) + " and cannot be modified.\nHowever you can re-import via CONSO File.");
                                return false;
                            }
                        }
                        //--
                        #region CD FILE PATH SELECTED
                        //-----------------------------------------------------------------------
                        //-- CD FILE PATH SELECTED
                        if (cmbCSVFormNo.Text != T_FormNo.F24QForm16SalaryDetails && cmbCSVFormNo.Text != T_FormNo.F24QSalaryDetails)
                        {
                            //-----------------------------------------------------------------------
                            if (txtChallanCSVFilePath.Text.Trim() == "")
                            {
                                cmnService.J_UserMessage("Challan CSV file not selected");
                                btnSelectChallanCSVFile.Select();
                                return false;
                            }
                            // FILE SHOULD BE FVU
                            if (Path.GetExtension(txtChallanCSVFilePath.Text).ToUpper() != ".CSV")
                            {
                                cmnService.J_UserMessage("Selected Challan file should be a CSV file");
                                btnSelectChallanCSVFile.Select();
                                return false;
                            }
                            // FILE EXIST
                            if (cmnService.J_IsFileExist(txtChallanCSVFilePath.Text) == false)
                            {
                                cmnService.J_UserMessage("Selected Challan CSV file not found");
                                btnSelectChallanCSVFile.Select();
                                return false;
                            }
                            // FILE OPEN
                            string strCDPath = txtChallanCSVFilePath.Text.ToString();
                            //
                            if (TdsMan.T_isFileOpenOrReadOnly(ref strCDPath) == true)
                            {
                                cmnService.J_UserMessage("Selected Challan CSV file is open");
                                btnSelectChallanCSVFile.Select();
                                return false;
                            }
                            #endregion

                        }
                        //--
                        #region DD FILE PATH SELECTED
                        //-----------------------------------------------------------------------
                        //-- DD FILE PATH SELECTED
                        //-----------------------------------------------------------------------
                        if (txtDeducteeCSVFilePath.Text.Trim() == "")
                        {
                            cmnService.J_UserMessage("Deductee CSV file not selected");
                            btnSelectDeducteeCSVFile.Select();
                            return false;
                        }
                        // FILE SHOULD BE FVU
                        if (Path.GetExtension(txtDeducteeCSVFilePath.Text).ToUpper() != ".CSV")
                        {
                            cmnService.J_UserMessage("Selected Deductee file should be a CSV file");
                            btnSelectDeducteeCSVFile.Select();
                            return false;
                        }
                        // FILE EXIST
                        if (cmnService.J_IsFileExist(txtDeducteeCSVFilePath.Text) == false)
                        {
                            cmnService.J_UserMessage("Selected Deductee CSV file not found");
                            btnSelectDeducteeCSVFile.Select();
                            return false;
                        }
                        // FILE OPEN
                        string strDDPath = txtDeducteeCSVFilePath.Text.ToString();
                        //
                        if (TdsMan.T_isFileOpenOrReadOnly(ref strDDPath) == true)
                        {
                            cmnService.J_UserMessage("Selected Deductee CSV file is open");
                            btnSelectDeducteeCSVFile.Select();
                            return false;
                        }
                        #endregion
                        //--
                    }
                }
                return true;
            }
            catch (Exception err_handler)
            {
                cmnService.J_UserMessage(err_handler.Message);
                return false;
            }
        }
        #endregion

