        #region CREATE_TEMP_TABLES_SQL
        private bool CREATE_TEMP_TABLES_SQL(long FaYearId)
        {
            try
            {
                //MessageBox.Show("1");
                #region T_tblTEMP_CHALLAN_DETAILS
                dmlService.J_BeginTransaction();
                //MessageBox.Show("2");
                if (dmlService.J_IsDatabaseObjectExist("" + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS + "") == true)
                {
                    //MessageBox.Show("2.1");
                    strSQL = "DROP TABLE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS + "";
                    dmlService.J_ExecSql(strSQL);
                }
                //MessageBox.Show("3");
                if (dmlService.J_IsDatabaseObjectExist("" + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS + "") == false)
                {
                    //MessageBox.Show("3.1");
                    if (tbcExcelImport.SelectedTab == tbpValidateCSVFile)
                    {
                        if (FaYearId >= T_FinancialYearID.F2026_27ID)
                            strSQL = @"CREATE TABLE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS + @" (
                                            " + cmnService.J_GetDataType("RUNNING_SERIAL_NO", J_ColumnType.String) + @",
                                            " + cmnService.J_GetDataType("TDS", J_ColumnType.String) + @",
                                            " + cmnService.J_GetDataType("INTEREST", J_ColumnType.String) + @",
                                            " + cmnService.J_GetDataType("FEE", J_ColumnType.String) + @",
                                            " + cmnService.J_GetDataType("PENALTY", J_ColumnType.String) + @",
                                            " + cmnService.J_GetDataType("TOTAL_TAX_DEPOSITED", J_ColumnType.String) + @",
                                            " + cmnService.J_GetDataType("BSR_CODE", J_ColumnType.String, 255) + @",
                                            " + cmnService.J_GetDataType("DATE_TAX_DEPOSITED", J_ColumnType.String) + @",
                                            " + cmnService.J_GetDataType("TRF_VCH_CHLN_NO", J_ColumnType.String, 255) + @",
                                            " + cmnService.J_GetDataType("BOOK_ENTRY", J_ColumnType.String) + @",
                                            " + cmnService.J_GetDataType("MINOR_HEAD", J_ColumnType.String, 255) + @")";
                        else
                            strSQL = @"CREATE TABLE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS + @" (
                                            " + cmnService.J_GetDataType("RUNNING_SERIAL_NO", J_ColumnType.String) + @",
                                            " + cmnService.J_GetDataType("TDS", J_ColumnType.String) + @",
                                            " + cmnService.J_GetDataType("SURCHARGE", J_ColumnType.String) + @",
                                            " + cmnService.J_GetDataType("EDUCATION_CESS", J_ColumnType.String) + @",
                                            " + cmnService.J_GetDataType("INTEREST", J_ColumnType.String) + @",
                                            " + cmnService.J_GetDataType("FEE", J_ColumnType.String) + @",
                                            " + cmnService.J_GetDataType("OTHERS", J_ColumnType.String) + @",
                                            " + cmnService.J_GetDataType("TOTAL_TAX_DEPOSITED", J_ColumnType.String) + @",
                                            " + cmnService.J_GetDataType("BSR_CODE", J_ColumnType.String, 255) + @",
                                            " + cmnService.J_GetDataType("DATE_TAX_DEPOSITED", J_ColumnType.String) + @",
                                            " + cmnService.J_GetDataType("TRF_VCH_CHLN_NO", J_ColumnType.String, 255) + @",
                                            " + cmnService.J_GetDataType("BOOK_ENTRY", J_ColumnType.String) + @",
                                            " + cmnService.J_GetDataType("MINOR_HEAD", J_ColumnType.String, 255) + @")";
                    }
                    else
                    {
                        if (FaYearId < T_FinancialYearID.F2026_27ID)
                            strSQL = @"CREATE TABLE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS + @" (
                                                " + cmnService.J_GetDataType("CHALLAN_DETAILS_ID", J_Identity.YES) + @",
                                                " + cmnService.J_GetDataType("RUNNING_SERIAL_NO_ORDER", J_ColumnType.Integer) + @",
                                                " + cmnService.J_GetDataType("RUNNING_SERIAL_NO", J_ColumnType.Integer) + @",
                                                " + cmnService.J_GetDataType("RUNNING_SERIAL_NO_CELL", J_ColumnType.Char) + @",
                                                " + cmnService.J_GetDataType("SECTION_NAME", J_ColumnType.String, 255) + @",
                                                " + cmnService.J_GetDataType("SECTION_NAME_CELL", J_ColumnType.Char) + @",
