                                                                                 TdsMan.T_WriteField(strReason_428) + TdsMan.T_WriteField((Convert.ToString((char)(intColumnValue + 14)) + (Convert.ToString(intLineNumber + 1)))) +
                                                                                 TdsMan.T_WriteField(strCertificateNo) + TdsMan.T_WriteField((Convert.ToString((char)(intColumnValue + 15)) + (Convert.ToString(intLineNumber + 1)))) + TdsMan.T_WriteField("0"));
                                #endregion
                            }
                            #endregion
                        }
                    }
                    myDataSet.Dispose();
                    myCommand.Dispose();

                    StreamWriterDeductee.Flush();
                    StreamWriterDeductee.Close();


                    #endregion

                    #region TRANSFERRING TO DATA FROM TEXT TO ACCESS

                    //TABLE NAME TO HOLD DATA
                    tableName = TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS;

                    //TEXT FILE NAME
                    textfileName = "DeducteeDetails";

                    TdsMan.T_ReplaceDoubleQuotesinFile(strTemporaryfileDeducteePath, true);

                    ImportTextToTables(tableName, textfileName, strTemporaryfileDeducteePath, false);

                    // DELETE THE TXT FILE
                    if (File.Exists(strTemporaryfileDeducteePath) == true)
                        File.Delete(strTemporaryfileDeducteePath);

                    #endregion

                    #region UPDATE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS + "

                    //Creation of temp table through SELECT ... INTO ... 
                    if (J_Var.J_pDatabaseType == J_DatabaseType.SqlServer)
                        strSQL = @"SELECT " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + @".CHALLAN_SERIAL_NO, 
                                          COUNT(" + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + @".CHALLAN_SERIAL_NO) AS C_NO_OF_DEDUCTEES, 
                                          SUM(ISNULL(CAST(" + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + @".TOTAL_TAX_DEPOSITED AS FLOAT),0)) AS C_CTRL_TOT_TAX 
                                   INTO " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_SUMM + @"
                                   FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + @"
                                   GROUP BY " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + @".CHALLAN_SERIAL_NO";
                    else if (J_Var.J_pDatabaseType == J_DatabaseType.MsAccess)
                        strSQL = @"SELECT " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + @".CHALLAN_SERIAL_NO, 
                                      COUNT(" + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + @".CHALLAN_SERIAL_NO) AS C_NO_OF_DEDUCTEES, 
                                      SUM(" + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + @".TOTAL_TAX_DEPOSITED) AS C_CTRL_TOT_TAX 
                               INTO " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_SUMM + @"
                               FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + @"
                               GROUP BY " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + @".CHALLAN_SERIAL_NO";
                    if (dmlService.J_ExecSql(strSQL) == false)
                    {
                        con.Close();
                        con.Dispose();
                        return false;
                    }

                    strSQL = @"UPDATE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS + @"
                               INNER JOIN 
                                   " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_SUMM + @"
                               ON  " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS + @".RUNNING_SERIAL_NO = " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_SUMM + @".CHALLAN_SERIAL_NO
                               SET " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS + @".CTRL_TOT_TAX     = " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_SUMM + @".C_CTRL_TOT_TAX,
                                   " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS + @".NO_OF_DEDUCTEES  = " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_SUMM + @".C_NO_OF_DEDUCTEES";
                    if (dmlService.J_ExecSql(strSQL) == false)
                    {
                        con.Close();
                        con.Dispose();
                        return false;
                    }

                    if (dmlService.J_IsDatabaseObjectExist(TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_SUMM) == true)
                    {
                        strSQL = "DROP TABLE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_SUMM;
                        dmlService.J_ExecSql(strSQL);
                        //if (dmlService.J_ExecSql(strSQL) == false)
                        //{
                        //    con.Close();
                        //    con.Dispose();
                        //    return false;
                        //}
                    }

                    #endregion

                    #endregion
                    //
                }

                myDataSet.Dispose();
                myCommand.Dispose();

                con.Close();
                con.Dispose();
                //
                intLN = 0;
                return true;
                //############################################
            }
            catch (Exception e)
            {
                //strErrorMessage = "Invalid data format in Excel file, please check. " + intLN;
                //-- 2015/10/14
                cmnService.J_UserMessage(e.Message);
                con.Close();
                con.Dispose();
                return false;
            }
        }
