                            "     OR     ISNUMERIC(" + strMidSubString + "(" + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ".DEDUCTEE_PAN, 5, 1)) <> 0 " +
                            "     OR     ISNUMERIC(" + strMidSubString + "(" + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ".DEDUCTEE_PAN, 6, 4))  = 0 " +
