                        string strPANSectionCondition = "";
                        if (J_Var.J_pDatabaseType == J_DatabaseType.MsAccess)
                        {
                            strPANSectionCondition =
                                " InStr(1, UCase(SEC.PAN_4TH_CHAR_ALLOWED), " +
