                            strPANSectionCondition =
                                " CHARINDEX(" +
                                " SUBSTRING(UPPER(LTRIM(RTRIM(T.DEDUCTEE_PAN))), 4, 1)," +
                                " UPPER(SEC.PAN_4TH_CHAR_ALLOWED)) = 0 ";
                        }
                        strSQL = "SELECT COUNT(*) " +
                                "FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + " AS T " +
                                "INNER JOIN " +
                                "   (SELECT SECTION_NO, PAN_4TH_CHAR_ALLOWED " +
                                "    FROM MST_SECTION " +
                                "    WHERE FORM_NAME = '" + strFormNo + "' " +
                                "    AND VALID_UPTO_ASST_ID = " + intSectionAssID + ") AS SEC " +
                                "ON T.[SECTION] = SEC.SECTION_NO " +
                                "WHERE SEC.PAN_4TH_CHAR_ALLOWED IS NOT NULL " +
                                "AND LTRIM(RTRIM(SEC.PAN_4TH_CHAR_ALLOWED)) <> '' " +
                                "AND T.DEDUCTEE_PAN IS NOT NULL " +
                                "AND LTRIM(RTRIM(T.DEDUCTEE_PAN)) <> '' " +
                                // Section should not already have an error
                                "AND NOT EXISTS " +
                                "   (SELECT 1 " +
                                "    FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_ERR_VALIDATION + " AS E " +
                                "    WHERE E.ERR_SHEET = '" + strSheetName + "' " +
                                "    AND E.ERR_CELL = T.SECTION_CELL) " +
                                // PAN should not already have an error
