                                int intRemittanceAssID = 0;
                                if (Support.GetItemData(cmbCSVFinancialYear, cmbCSVFinancialYear.SelectedIndex) < T_FinancialYearID.F2026_27ID)
                                    intRemittanceAssID = T_FinancialYearID.F2025_26ID;
                                strSQL = " SELECT COUNT(*)" +
                                         " FROM   (((" + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + " " +
                                         "        INNER JOIN " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS + "" +
                                         "         ON " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ".CHALLAN_SERIAL_NO = " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS + ".RUNNING_SERIAL_NO) " +
                                         "        LEFT JOIN (SELECT REMITTANCE_CODE " +
                                         "                   FROM   MST_REMITTANCE WHERE INACTIVE_FLAG = 0 AND VALID_UPTO_ASST_ID = " + intRemittanceAssID + ") AS REMITT " +
                                         "         ON " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ".REMITTANCE = REMITT.REMITTANCE_CODE)" +
                                         "        LEFT JOIN (SELECT ERR_ROW " +
                                         "                   FROM   " + TDSMAN.Classes.TDSMAN.T_tblTEMP_ERR_VALIDATION + " " +
                                         "                   WHERE  ERR_SHEET = '" + strSheetName + "') AS ERR_V" +
                                         "         ON " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ".DEDUCTEE_SERIAL_NO = ERR_V.ERR_ROW) " +
                                         " WHERE  REMITT.REMITTANCE_CODE      IS NULL " +
                                         " AND    ERR_V.ERR_ROW              IS NULL " +
                                         " AND    " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ".REMITTANCE <> '' ";

                                lngRowCount = cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL)));

                                if (lngRowCount > 0)
                                {
                                    strSQL = " INSERT INTO " + TDSMAN.Classes.TDSMAN.T_tblTEMP_ERR_VALIDATION + "(ERR_TYPE, ERR_ROW, ERR_COLUMN, ERR_SHEET)" +
                                        "     SELECT '" + T_Error_Type.VALIDITY_CHECK + "'," +
                                        "            " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ".DEDUCTEE_SERIAL_NO AS ERR_ROW," +
                                        "            'REMITTANCE'," +
                                        "            '" + strSheetName + "'" +
                                        "     FROM  (((" + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + " " +
                                        "           INNER JOIN " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS + " " +
                                        "           ON     " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ".CHALLAN_SERIAL_NO = " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS + ".RUNNING_SERIAL_NO) " +
                                        "           LEFT JOIN (SELECT ERR_ROW " +
