                dmlService.J_ExecSql(strSQL);
                //
                strSQL = @"UPDATE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_F16_SALARY_DETAILS +
                        @" SET    LANDLORD_PAN_COUNT = LANDLORD_PAN_COUNT + 1 
                           WHERE  PAN_LANDLORD3 <> ''";
                dmlService.J_ExecSql(strSQL);
                //
                strSQL = @"UPDATE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_F16_SALARY_DETAILS +
                        @" SET    LANDLORD_PAN_COUNT = LANDLORD_PAN_COUNT + 1 
                           WHERE  PAN_LANDLORD4 <> ''";
                dmlService.J_ExecSql(strSQL);
                //
                #endregion

