        #region CALCULATE_SUM_ANNEXIII
        private bool CALCULATE_SUM_ANNEXIII()
        {
            try
            {
                //--
                string strUpper = "";
                if (J_Var.J_pDatabaseType == J_DatabaseType.SqlServer)
                {
                    strUpper = "UPPER";
                }
                else if (J_Var.J_pDatabaseType == J_DatabaseType.MsAccess)
                {
                    strUpper = "UCASE";
                }
                //--
                string strSheetName = T_Sheet_Name.ANNEXURE_III;
                //--
                #region BALANCE AMOUNT
                strSQL = @" UPDATE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_ANNEXURE_III +
                         @" SET   BALANCE_AMOUNT = " + cmnService.J_SQLDBFormat(TDSMAN.Classes.TDSMAN.T_tblTEMP_ANNEXURE_III + ".TS_GS_SEC_17_1", J_SQLColFormat.ConvertToMoney);
                dmlService.J_ExecSql(strSQL);
                #endregion   

                #region AGGREGATE OF 16(iii) & 16(ia)
                strSQL = @" UPDATE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_ANNEXURE_III +
                         @" SET   US_16_AGGREGATE = " + cmnService.J_SQLDBFormat(TDSMAN.Classes.TDSMAN.T_tblTEMP_ANNEXURE_III + ".US_16_III", J_SQLColFormat.ConvertToMoney) + " + " +
                                                         cmnService.J_SQLDBFormat(TDSMAN.Classes.TDSMAN.T_tblTEMP_ANNEXURE_III + ".US_16_IA", J_SQLColFormat.ConvertToMoney);
                //--
                dmlService.J_ExecSql(strSQL);
                #endregion

                #region INCOME CHARGEABLE UNDER THE HEAD SALARIES
                strSQL = @" UPDATE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_ANNEXURE_III +
                         @" SET   INCOME_CHARGEABLE = " + cmnService.J_SQLDBFormat(TDSMAN.Classes.TDSMAN.T_tblTEMP_ANNEXURE_III + ".BALANCE_AMOUNT", J_SQLColFormat.ConvertToMoney) + " - " +
                                                cmnService.J_SQLDBFormat(TDSMAN.Classes.TDSMAN.T_tblTEMP_ANNEXURE_III + ".US_16_AGGREGATE", J_SQLColFormat.ConvertToMoney);
                dmlService.J_ExecSql(strSQL);
                #endregion

                #region BALANCE < INCOME CHARGEABLE UNDER THE HEAD SALARIES
                strSQL = "SELECT COUNT(*)" +
                            "     FROM   " + TDSMAN.Classes.TDSMAN.T_tblTEMP_ANNEXURE_III + "" +
                            "     WHERE  " + cmnService.J_SQLDBFormat("BALANCE_AMOUNT", J_SQLColFormat.ConvertToMoney) + " < " +
                            "            " + cmnService.J_SQLDBFormat("INCOME_CHARGEABLE", J_SQLColFormat.ConvertToMoney) + " " +
                            "     AND    BALANCE_AMOUNT_CELL NOT IN (SELECT ERR_CELL FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_ERR_VALIDATION + " " +
                            "                                      WHERE ERR_SHEET = '" + strSheetName + "')";
                //
                lngRowCount = cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL)));

                if (lngRowCount > 0)
                {
                    // OTHER_SEC_DESC2
                    strSQL = " INSERT INTO " + TDSMAN.Classes.TDSMAN.T_tblTEMP_ERR_VALIDATION + "(ERR_TYPE, ERR_CELL, ERR_COLUMN, ERR_SHEET, ERR_COLOR, ERR_FORM_NO)" +
                        "     SELECT '" + T_Error_Type.VALIDITY_CHECK + "'," +
                        "            " + TDSMAN.Classes.TDSMAN.T_tblTEMP_ANNEXURE_III + ".TS_GS_SEC_17_1_CELL AS ERROR_CELL," +
                        "            'TS_GS_SEC_17_1_CELL'," +
                        "            '" + strSheetName + "'," +
                        "            '" + T_Error_Type_Color.VALIDITY_CHECK + "'," +
                        "            '" + cmbFormNo.Text + "'" +
                        "     FROM   " + TDSMAN.Classes.TDSMAN.T_tblTEMP_ANNEXURE_III + " LEFT JOIN " +
                        "           (SELECT ERR_CELL " +
                        "            FROM   " + TDSMAN.Classes.TDSMAN.T_tblTEMP_ERR_VALIDATION + " " +
                        "            WHERE  ERR_SHEET = '" + strSheetName + "') AS ERR_V " +
                        "     ON     " + TDSMAN.Classes.TDSMAN.T_tblTEMP_ANNEXURE_III + ".TS_GS_SEC_17_1_CELL = ERR_V.ERR_CELL " +
                        "     WHERE  ERR_V.ERR_CELL       IS NULL " +
                        "     AND    " + cmnService.J_SQLDBFormat("BALANCE_AMOUNT_CELL", J_SQLColFormat.ConvertToMoney) + " < " +
                        "            " + cmnService.J_SQLDBFormat("INCOME_CHARGEABLE", J_SQLColFormat.ConvertToMoney);

                    //                
                    if (dmlService.J_ExecSql(strSQL) == false)
                        return false;
                }
                #endregion
                
                #region GROSS TOTAL INCOME
