                        lblSDCompany.Text = Company;
                        //
                        lblSDFormNo.Text = "24Q";
                        //
                        strSQL = "SELECT TAN_NO " +
                            "     FROM   MST_COMPANY " +
                            "     WHERE  COMPANY_ID = " + CompanyId;
