                        else
                            lblSDNewDeductees.BackColor = System.Drawing.Color.Cornsilk;
                        //
                        lblSDNewDeductees.Text = Convert.ToString(lngNewDeducteesCreated);
                        //--
                        LoadSD16Grid();
                        //
                    }
                    else
                    {
                        //--
                        //tbcExcelImport.TabPages.Remove(tbpValidateExcelFile);
                        blnOpenTabPage = true;
                        tbcExcelImport.SelectTab(tbpImportExcelFile);
                        //
                        lblFinancialYear.Text = FinancialYear;
                        lblFinancialYearId.Text = FinancialYearId.ToString();
                        lblQtr.Text = Quarter;
                        lblFormNo.Text = strDisplayFormNo;
                        lblFormNo.Tag = FormNo;
                        lblCompanyName.Text = Company;
                        lblTANNo.Text = Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT TAN_NO FROM MST_COMPANY WHERE COMPANY_ID = " + CompanyId));
                        txtTotalDeducteeRecords.Text = Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(*) AS COUNT_DEDUCTEE_DETAIL_ID FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ""));
                        //
                        if (chkEnterDeducteeDetailsOnly.Checked == false)
                        {
                            txtTotalChallanRecords.Enabled = true;
                            txtTotalChallanAmount.Enabled = true;
                            //
                            txtTotalChallanRecords.Text = Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(*) AS COUNT_CHALLAN_ID FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS + ""));
                            //
                            txtTotalChallanAmount.Text = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT SUM(" + cmnService.J_SQLDBFormat("TOTAL_TAX_DEPOSITED", J_SQLColFormat.ConvertToMoney) + " ) AS SUM_TOT_TAX FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS + "")) == "" ? "0" : Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT SUM(" + cmnService.J_SQLDBFormat("TOTAL_TAX_DEPOSITED", J_SQLColFormat.ConvertToMoney) + " ) AS SUM_TOT_TAX FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS + ""))));
                        }
                        else
                        {
                            txtTotalChallanRecords.Text = "0";
                            txtTotalChallanAmount.Text = "0.00";
                            txtTotalChallanRecords.Enabled = false;
                            txtTotalChallanAmount.Enabled = false;
                        }
                        //
                        txtTotalDeducteeTDS.Text = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT SUM(" + cmnService.J_SQLDBFormat("TOTAL_TAX_DEDUCTED", J_SQLColFormat.ConvertToMoney) + " ) AS SUM_TOTAL_AMOUNT FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + "")) == "" ? "0" : Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT SUM(" + cmnService.J_SQLDBFormat("TOTAL_TAX_DEDUCTED", J_SQLColFormat.ConvertToMoney) + ") AS SUM_TOTAL_AMOUNT FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ""))));
                        txtAmountPaid.Text = string.Format("{0:0.00}", Convert.ToDouble(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT SUM(" + cmnService.J_SQLDBFormat("AMOUNT_PAID", J_SQLColFormat.ConvertToMoney) + ") AS PAYMENT_AMOUNT FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + "")) == "" ? "0" : Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT SUM(" + cmnService.J_SQLDBFormat("AMOUNT_PAID", J_SQLColFormat.ConvertToMoney) + ") AS PAYMENT_AMOUNT FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ""))));
                        //----
                        if (lngNewDeducteesCreated > 0)
                            lblNewDeducteesFound.BackColor = Color.LightGreen;
                        else
                            lblNewDeducteesFound.BackColor = System.Drawing.Color.Cornsilk;
                        //
                        lblNewDeducteesFound.Text = Convert.ToString(lngNewDeducteesCreated);
                        //--
                        if (lngNewDeducteesCreated > TDSMAN.Classes.TDSMAN.T_MAX_REC_EXCEL_IMPORT_ALERT)
                            btnOpenNewDeducteesFound.Visible = false;
                        //--
                        if (chkEnterDeducteeDetailsOnly.Checked == true)
                        {
                            dgcViewChallan.Visible = false;
                            BtnExit.Text = "Exit";
                            //--
                            dgcViewDeductee.Visible = true;
                            //--------------------------------------------------
                            //A particular ID wise retriving the data from database
                            if (LoadDeducteeDetailsGrid(0, Convert.ToInt32(lblFinancialYearId.Text)) == false)
                            {
                                return false;
                            }
                        }
                        else
                            LoadChallanGrid(FinancialYearId);
                        //
                    }
                    return true;
                }
                return false;
            }
            catch
            {
                return false;
            }
        }
