                          "       " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ".DEDUCTEE_PAN              AS PAN," +
                          "       " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ".DEDUCTEE_NAME             AS DEDUCTEE_NAME," +
                          "       " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ".[SECTION]                 AS SECTION_NAME," +
                          "       " + cmnService.J_SQLDBFormat(TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ".DATE_PAYMENT", J_SQLColFormat.DateFormatDDMMYYYY) + " AS DATE_PAYMENT," +
                          "       " + cmnService.J_SQLDBFormat(TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ".AMOUNT_PAID", J_SQLColFormat.ConvertToMoney) + " AS AMOUNT_PAID," +
                          "       " + cmnService.J_SQLDBFormat(TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ".TOTAL_TAX_DEDUCTED", J_SQLColFormat.ConvertToMoney) + " AS TOTAL_TAX_DEDUCTED," +
                          "       " + cmnService.J_SQLDBFormat(TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ".TOTAL_TAX_DEPOSITED", J_SQLColFormat.ConvertToMoney) + " AS TOTAL_TAX_DEPOSITED ";
                if (ChallanId > 0)
                {
                    strQuery = strQuery + "FROM   " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ", " +
                    "       " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS + " " +
                    "WHERE  " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ".CHALLAN_SERIAL_NO = " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS + ".RUNNING_SERIAL_NO " +
                    "AND    " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_DETAILS + ".CHALLAN_DETAILS_ID = " + ChallanId;
                }
                else
                {
                    strQuery = strQuery + "FROM   " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + " ";
                }
                //-----------------------------------------------------------
                strSQL = strQuery + " ORDER BY " + strOrderBy;
                //-----------------------------------------------------------
                if (dsetGridClone != null) dsetGridClone.Clear();
                dsetGridClone = dmlService.J_ShowDataInGrid(ref dgcViewDeductee, strSQL, strMatrixDeducteeDetails);       //Show Data into the Grid
                //--
                return true;
            }
            catch
            {
                return false;
            }
        }
        #endregion

