                             "SET    " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ".CHALLAN_SERIAL_NO = " + cmnService.J_SQLDBFormat("TRN_CHALLAN.SL_NO", J_SQLColFormat.ConvertToString) + " " +
                             "WHERE  TRN_CHALLAN.BASIC_INFO_ID = " + BasicInfoID;
                    if (dmlService.J_ExecSql(strSQL) == false)
                    {
                        return false;
                    }
                }
                //}
                //else if (tbcExcelImport.SelectedTab == tbpValidateCSVFile)
                //{
                //    if (rbnCSVIncremental.Checked == true)
                //    {
                //        //
                //        strSQL = "UPDATE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + " " +
