                //                strSQL = @"UPDATE TRN_CHALLAN SET TRN_CHALLAN.INTEREST_ALLOCATED = TRN_CHALLAN.INTEREST,
                //                                              TRN_CHALLAN.OTHERS_ALLOCATED = TRN_CHALLAN.OTHERS 
