        #region INSERT_DEDUCTEE_DATA
        public bool INSERT_DEDUCTEE_DATA(long BasicInfoID, long FAYearId, string FormNo, bool DeducteeDetailsOnly)
        {
            try
            {//--
                string strUpper = "";
                if (J_Var.J_pDatabaseType == J_DatabaseType.SqlServer)
                {
                    strUpper = "UPPER";
                }
                else if (J_Var.J_pDatabaseType == J_DatabaseType.MsAccess)
                {
                    strUpper = "UCASE";
                }
                //--
                #region TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS (EMPLOYEE_SERIAL_NO)
                if (dmlService.J_IsDatabaseObjectExist(TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS, "EMPLOYEE_SERIAL_NO") == false)
                {
                    //if (tbcExcelImport.SelectedTab == tbpValidateExcelFile)
