                            "," + cmnService.J_SQLDBFormat(TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ".EMAIL", J_ColumnType.String, J_SQLColFormat.NullCheck) + " " +
                            "," + cmnService.J_SQLDBFormat(TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ".CONTACT_NO", J_ColumnType.String, J_SQLColFormat.NullCheck) + "" +
                            "," + cmnService.J_SQLDBFormat(TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ".ADDRESS", J_ColumnType.String, J_SQLColFormat.NullCheck) + " ";
                    if (FormNo == T_FormNo.F27EQ)
                        strSQL = strSQL + ", " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ".NON_RESIDENT " +
                                          ", " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ".PERMANENT_ESTABLISHMENT ";// +
                                          //", " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ".CHALLAN_NO " +
                                          //", " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ".CHALLAN_DATE ";

                    if (FormNo == T_FormNo.F27Q || FormNo == T_FormNo.F27EQ)
                        strSQL = strSQL + "," + cmnService.J_SQLDBFormat(strTAX_115BAC1A, J_SQLColFormat.Case_End) + " ";

                    //    strSQL = strSQL + " ";
                    if (FormNo == T_FormNo.F26Q || FormNo == T_FormNo.F27Q)
                        strSQL = strSQL + "," + cmnService.J_SQLDBFormat(strSEC194N_EXCESS_1CRORE_AMOUNT, J_SQLColFormat.Case_End) +
                                      "," + cmnService.J_SQLDBFormat(strSEC194N_EXCESS_3CRORE_AMOUNT, J_SQLColFormat.Case_End) ;

                    strSQL = strSQL + "," + strUpper + "(" + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ".DEDUCTEE_PAN)" +
                                      "," + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ".DEDUCTEE_NAME";
                    //
                    if (DeducteeDetailsOnly == true)
                    {
                        strSQL = strSQL + " FROM (((((" + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + " " +
                            "               LEFT  JOIN (SELECT REASON_ID, " +
                            "                              REASON " +
                            "                       FROM MST_REASON " +
                            "                       WHERE FORM_NO = '" + FormNo + "') AS REASON_ASPER_FORM " +
                            "                       ON " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ".REASON = REASON_ASPER_FORM.REASON) " +
                            "               LEFT  JOIN MST_SECTION " +
                            "                       ON " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ".SECTION = MST_SECTION.SECTION_NO) " +
                            "               LEFT  JOIN MST_COUNTRY " +
                            "                       ON " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ".COUNTRY = MST_COUNTRY.COUNTRY_CODE) " +
                            "               LEFT  JOIN MST_TDS_APPLICABILITY " +
                            "                       ON " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ".TDS_APPLICABILITY = MST_TDS_APPLICABILITY.TDS_APPLICABILITY_CODE) " +
                            "               LEFT  JOIN MST_REMITTANCE " +
                            "                       ON " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ".REMITTANCE = MST_REMITTANCE.REMITTANCE_CODE) ";// +
                                                                                                                                                               //"               WHERE TRN_CHALLAN.BASIC_INFO_ID = " + BasicInfoID + " ";
                        if (FAYearId > T_FinancialYearID.F2012_13ID) //-- ANIK @ 2015/07/10
                            strSQL = strSQL + " WHERE   MST_SECTION.FORM_NAME ='" + lblFormNo.Tag + "'  AND MST_SECTION.DIFF_RATES = 0 ";
                    }
                    else
                    {
                        strSQL = strSQL + " FROM ((((((" + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + " " +
                            "               INNER JOIN TRN_CHALLAN " +
                            "                       ON " + cmnService.J_SQLDBFormat(TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ".CHALLAN_SERIAL_NO", J_SQLColFormat.ConvertToNumeric) + " = TRN_CHALLAN.SL_NO)" +
                            "               LEFT  JOIN (SELECT REASON_ID, " +
                            "                              REASON " +
                            "                       FROM MST_REASON " +
                            "                       WHERE FORM_NO = '" + FormNo + "') AS REASON_ASPER_FORM " +
                            "                       ON " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ".REASON = REASON_ASPER_FORM.REASON) " +
                            "               LEFT  JOIN MST_SECTION " +
                            "                       ON " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ".SECTION = MST_SECTION.SECTION_NO) " +
                            "               LEFT  JOIN MST_COUNTRY " +
                            "                       ON " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ".COUNTRY = MST_COUNTRY.COUNTRY_CODE) " +
                            "               LEFT  JOIN MST_TDS_APPLICABILITY " +
                            "                       ON " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ".TDS_APPLICABILITY = MST_TDS_APPLICABILITY.TDS_APPLICABILITY_CODE) " +
                            "               LEFT  JOIN MST_REMITTANCE " +
                            "                       ON " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ".REMITTANCE = MST_REMITTANCE.REMITTANCE_CODE) " +
                            "               WHERE TRN_CHALLAN.BASIC_INFO_ID = " + BasicInfoID + " ";
                        if (FAYearId > T_FinancialYearID.F2012_13ID) //-- ANIK @ 2015/07/10
                            strSQL = strSQL + " AND   MST_SECTION.FORM_NAME ='" + lblFormNo.Tag + "'  AND MST_SECTION.DIFF_RATES = 0 ";
                    }
                    //
                    if (FAYearId >= T_FinancialYearID.F2026_27ID && FormNo == T_FormNo.F27Q)
                    {
                        //strSQL = strSQL + " AND   MST_REMITTANCE.VALID_UPTO_ASST_ID = 0 AND MST_REMITTANCE.INACTIVE_FLAG = 0";
                        strSQL = strSQL + @" AND (MST_REMITTANCE.REMITTANCE_ID IS NULL OR (MST_REMITTANCE.VALID_UPTO_ASST_ID = 0 AND MST_REMITTANCE.INACTIVE_FLAG = 0))";
                    }
                    else if (FAYearId < T_FinancialYearID.F2026_27ID && FormNo == T_FormNo.F27Q)
                        strSQL = strSQL + " AND   MST_REMITTANCE.VALID_UPTO_ASST_ID = " + T_FinancialYearID.F2025_26ID + " AND MST_REMITTANCE.INACTIVE_FLAG = 0";
                    //--
                    #endregion
                }
                //strSQL = strSQL + "ORDER BY " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ".DEDUCTEE_SERIAL_NO";
                strSQL = strSQL + " ORDER BY " + cmnService.J_SQLDBFormat(TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + ".DEDUCTEE_SERIAL_NO", J_SQLColFormat.ConvertToNumeric);
                //-----------------------------------------------------------
                if (dmlService.J_ExecSql(strSQL) == false)
                {
                    return false;
                }
                //-- POPULATING RATE
                if (FormNo != T_FormNo.F24Q && TDSMAN.Classes.TDSMAN.T_EnableAutoCalculateTdsRate == true)
                {
                    if (FAYearId < T_FinancialYearID.F2026_27ID)
                    {
                        if (J_Var.J_pDatabaseType == J_DatabaseType.MsAccess)
                        {
                            strSQL = "UPDATE TRN_DEDUCTEE_DETAILS " +
                                     "SET    RATE = FORMAT(((TAX_AMOUNT/PAYMENT_AMOUNT)*100), '0.0000')" +
                                     "WHERE  BASIC_INFO_ID = " + BasicInfoID;
                            if (dmlService.J_ExecSql(strSQL) == false)
                            {
                                return false;
                            }
                        }
                        else //-- 2016/07/30
                        {
                            //strSQL = "UPDATE TRN_DEDUCTEE_DETAILS " +
                            //         "SET    RATE = CONVERT(DECIMAL(15,4),((CAST(TAX_AMOUNT AS DECIMAL)/CAST(PAYMENT_AMOUNT AS DECIMAL))*100)) " +
                            //         "WHERE  BASIC_INFO_ID = " + BasicInfoID;
                            //-- 2017/03/27
                            strSQL = "UPDATE TRN_DEDUCTEE_DETAILS " +
                                     //"SET    RATE = CONVERT(DECIMAL(15,4),((CAST(TAX_AMOUNT AS DECIMAL(10,2))/CAST(PAYMENT_AMOUNT AS DECIMAL(10,2))) * 100)) " +
                                     "SET    RATE = CONVERT(DECIMAL(15,4),((CAST(TAX_AMOUNT AS DECIMAL(15,2))/CAST(PAYMENT_AMOUNT AS DECIMAL(15,2))) * 100)) " +
                                     "WHERE  BASIC_INFO_ID = " + BasicInfoID;
                            if (dmlService.J_ExecSql(strSQL) == false)
                            {
                                return false;
                            }
                        }
                    }
                    else if (FAYearId >= T_FinancialYearID.F2026_27ID)
                    {
                        if (J_Var.J_pDatabaseType == J_DatabaseType.MsAccess)
                        {
                            strSQL = "UPDATE TRN_DEDUCTEE_DETAILS " +
                                     "SET    RATE = FORMAT(((TOTAL_AMOUNT/PAYMENT_AMOUNT)*100), '0.0000')" +
                                     "WHERE  BASIC_INFO_ID = " + BasicInfoID;
                            if (dmlService.J_ExecSql(strSQL) == false)
                            {
                                return false;
                            }
                        }
                        else //-- 2016/07/30
                        {
                            //strSQL = "UPDATE TRN_DEDUCTEE_DETAILS " +
                            //         "SET    RATE = CONVERT(DECIMAL(15,4),((CAST(TAX_AMOUNT AS DECIMAL)/CAST(PAYMENT_AMOUNT AS DECIMAL))*100)) " +
                            //         "WHERE  BASIC_INFO_ID = " + BasicInfoID;
                            //-- 2017/03/27
                            strSQL = "UPDATE TRN_DEDUCTEE_DETAILS " +
                                     //"SET    RATE = CONVERT(DECIMAL(15,4),((CAST(TAX_AMOUNT AS DECIMAL(10,2))/CAST(PAYMENT_AMOUNT AS DECIMAL(10,2))) * 100)) " +
                                     "SET    RATE = CONVERT(DECIMAL(15,4),((CAST(TOTAL_AMOUNT AS DECIMAL(15,2))/CAST(PAYMENT_AMOUNT AS DECIMAL(15,2))) * 100)) " +
                                     "WHERE  BASIC_INFO_ID = " + BasicInfoID;
                            if (dmlService.J_ExecSql(strSQL) == false)
                            {
                                return false;
                            }
                        }
                    }
                }
                //--
                if (FAYearId < T_FinancialYearID.F2013_14ID)
                {
                    strSQL = "UPDATE TRN_DEDUCTEE_DETAILS " +
                             "INNER JOIN TRN_CHALLAN " +
                             "ON     TRN_DEDUCTEE_DETAILS.CHALLAN_ID = TRN_CHALLAN.CHALLAN_ID " +
                             "SET    TRN_DEDUCTEE_DETAILS.SECTION_ID = TRN_CHALLAN.SECTION_ID " +
                             "WHERE  TRN_CHALLAN.BASIC_INFO_ID = " + BasicInfoID;
                    if (dmlService.J_ExecSql(strSQL) == false)
                    {
                        return false;
                    }
                }
                //UPDATE DEDUCTED DATE TO BLANK IF TOTAL DEDUCTION IS ZERO
                strSQL = "UPDATE TRN_DEDUCTEE_DETAILS SET DEDUCTED_DATE = NULL WHERE TOTAL_AMOUNT = 0";
                if (dmlService.J_ExecSql(strSQL) == false)
                {
                    return false;
                }
                if (chkEnterDeducteeDetailsOnly.Checked == false)
                {
                    // INSERTING CONTROL TOTALS OF CHALLAN IN TEMP_TABLE
                    strSQL = " INSERT INTO " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_CONTROL_TOTALS + " " +
                    "                  (CHALLAN_ID, " +
                    "                  SUM_TAX_AMOUNT,  " +
                    "                  SUM_SURCHARGE_AMOUNT, " +
                    "                  SUM_CESS_AMOUNT,  " +
                    "                  SUM_TOTAL_AMOUNT,  " +
                    "                  SUM_TAX_DEPOSITED_AMOUNT)  " +
                    "      SELECT CHALLAN_ID,  " +
                    "             SUM(TAX_AMOUNT), " +
                    "             SUM(SURCHARGE_AMOUNT),  " +
                    "             SUM(CESS_AMOUNT),  " +
                    "             SUM(TOTAL_AMOUNT),  " +
                    "             SUM(TAX_DEPOSITED_AMOUNT)  " +
                    "      FROM   TRN_DEDUCTEE_DETAILS  " +
                    "      WHERE  BASIC_INFO_ID = " + BasicInfoID + "" +
                    "      GROUP  BY CHALLAN_ID";
                    if (dmlService.J_ExecSql(strSQL) == false)
                    {
                        return false;
                    }
                    //UPDATE CONTROL TOTALS OF CHALLAN TABLE USING TEMP TABLE
                    strSQL = "UPDATE TRN_CHALLAN" +
                    "                INNER JOIN  " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_CONTROL_TOTALS + " " +
                    "                  ON TRN_CHALLAN.CHALLAN_ID = " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_CONTROL_TOTALS + ".CHALLAN_ID " +
                    "         SET    TRN_CHALLAN.CTRL_TDS       = " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_CONTROL_TOTALS + ".SUM_TAX_AMOUNT," +
                    "                TRN_CHALLAN.CTRL_SURCHARGE = " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_CONTROL_TOTALS + ".SUM_SURCHARGE_AMOUNT," +
                    "                TRN_CHALLAN.CTRL_EDU_CESS  = " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_CONTROL_TOTALS + ".SUM_CESS_AMOUNT," +
                    "                TRN_CHALLAN.CTRL_TOT       = " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_CONTROL_TOTALS + ".SUM_TOTAL_AMOUNT," +
                    "                TRN_CHALLAN.CTRL_TOT_TAX   = " + TDSMAN.Classes.TDSMAN.T_tblTEMP_CHALLAN_CONTROL_TOTALS + ".SUM_TAX_DEPOSITED_AMOUNT" +
                    "         WHERE TRN_CHALLAN.BASIC_INFO_ID = " + BasicInfoID + " ";
                    if (dmlService.J_ExecSql(strSQL) == false)
                    {
                        return false;
                    }
                    //--
                    //if (tbcExcelImport.SelectedTab == tbpValidateCSVFile)
                    if (blnCSVImport == true)
                    {
                        strSQL = @"SELECT CHALLAN_ID FROM TRN_CHALLAN WHERE BASIC_INFO_ID = " + BasicInfoID;
                        DataSet ds;
                        ds = dmlService.J_ExecSqlReturnDataSet(strSQL);
                        if (ds == null || ds.Tables[0].Rows.Count == 0)
                            return false;
                        // Calculating the Tax amount based on each slab rate 
                        for (int i = 0; i < ds.Tables[0].Rows.Count; i++)
                        {
                            //ds.Tables[0].Rows[i]["CHALLAN_ID"];
                            //--
                            if (J_Var.J_pDatabaseType == J_DatabaseType.MsAccess)
                            {
                                ////strSQL = "UPDATE TRN_DEDUCTEE_DETAILS " +
                                ////     "INNER  JOIN " +
                                ////     "      (SELECT DCOUNT('DEDUCTEE_DETAIL_ID','TRN_DEDUCTEE_DETAILS','DEDUCTEE_DETAIL_ID <= ' & T.DEDUCTEE_DETAIL_ID & ' and  CHALLAN_ID = " + ds.Tables[0].Rows[i]["CHALLAN_ID"] + "') AS NEW_SL_NO," +
                                ////     "              DEDUCTEE_DETAIL_ID," +
                                ////     "              CHALLAN_ID " +
                                ////     "       FROM TRN_DEDUCTEE_DETAILS AS T " +
                                ////     "       WHERE CHALLAN_ID = " + ds.Tables[0].Rows[i]["CHALLAN_ID"] + ") AS T_NEW_SL_NO " +
                                ////     "ON  (TRN_DEDUCTEE_DETAILS.CHALLAN_ID = T_NEW_SL_NO.CHALLAN_ID) " +
                                ////     "AND (TRN_DEDUCTEE_DETAILS.DEDUCTEE_DETAIL_ID = T_NEW_SL_NO.DEDUCTEE_DETAIL_ID) " +
                                ////     "SET TRN_DEDUCTEE_DETAILS.SL_NO = T_NEW_SL_NO.NEW_SL_NO";
                                // Fetch records to update SL_NO in C# //-- 2025/07/29
                                int challanId = Convert.ToInt32(ds.Tables[0].Rows[i]["CHALLAN_ID"]);
                                strSQL = "SELECT DEDUCTEE_DETAIL_ID FROM TRN_DEDUCTEE_DETAILS WHERE CHALLAN_ID = " + challanId + " ORDER BY DEDUCTEE_DETAIL_ID";
                                DataSet dsDeductee = dmlService.J_ExecSqlReturnDataSet(strSQL);
                                if (dsDeductee == null) continue;
                                //--
                                int serial = 1;
                                foreach (DataRow row in dsDeductee.Tables[0].Rows)
                                {
                                    int detailId = Convert.ToInt32(row["DEDUCTEE_DETAIL_ID"]);
                                    strSQL = "UPDATE TRN_DEDUCTEE_DETAILS SET SL_NO = " + serial + " WHERE DEDUCTEE_DETAIL_ID = " + detailId;
                                    if (!dmlService.J_ExecSql(strSQL))
                                        return false;
                                    serial++;
                                }
                            }
                            else if (J_Var.J_pDatabaseType == J_DatabaseType.SqlServer) //ROW_NUMBER() OVER (PARTITION BY EMPLOYEE_SERIAL_NO ORDER BY EMPLOYEE_SERIAL_NO, PARTY_PAN, PAYMENT_DATE, DEDUCTEE_DETAIL_ID) 
                            {
                                strSQL = @"UPDATE TRN_DEDUCTEE_DETAILS 
                                   SET TRN_DEDUCTEE_DETAILS.SL_NO = T_NEW_SL_NO.SL_NO
                                   FROM TRN_DEDUCTEE_DETAILS
                                   INNER  JOIN (SELECT ROW_NUMBER() OVER (PARTITION BY CHALLAN_ID ORDER BY DEDUCTEE_DETAIL_ID) AS SL_NO, 
					                                   DEDUCTEE_DETAIL_ID 
				                                FROM TRN_DEDUCTEE_DETAILS 
				                                WHERE CHALLAN_ID = " + ds.Tables[0].Rows[i]["CHALLAN_ID"] + @") AS T_NEW_SL_NO
                                    ON  TRN_DEDUCTEE_DETAILS.DEDUCTEE_DETAIL_ID = T_NEW_SL_NO.DEDUCTEE_DETAIL_ID
                                    WHERE TRN_DEDUCTEE_DETAILS.CHALLAN_ID = " + ds.Tables[0].Rows[i]["CHALLAN_ID"];
                                if (dmlService.J_ExecSql(strSQL) == false)
                                {
                                    return false;
                                }
                            }
                        }
                    }
                }
                //
                return true;
            }
            catch (Exception e)
            {
                return false;
            }
        }

        #endregion

        #region INSERT_MASTER_DATA
        public bool INSERT_MASTER_DATA(string FormNo, long CompanyId)
        {
            try
            {
                string strUpper = "";
                if (J_Var.J_pDatabaseType == J_DatabaseType.SqlServer)
                {
                    strUpper = "UPPER";
                }
                else if (J_Var.J_pDatabaseType == J_DatabaseType.MsAccess)
                {
                    strUpper = "UCASE";
                }
                //
                if (FormNo == T_FormNo.F24QSalaryDetails)
                {
                    #region F24QSalaryDetails
                    //INSERTING NEW EMPLOYEES FOUND IN EXCEL TO THE MASTER
                    strSQL = "INSERT INTO MST_EMPLOYEE " +
                       "                 (EMPLOYEE_NAME," +
                       "                  EMPLOYEE_PAN," +
                       "                  COMPANY_ID," +
                       "                  GROUP_ID," +
                       "                  EMPLOYEE_REF) " +
                       "      SELECT      DEDUCTEE_NAME," +
                       "                  " + strUpper + "(DEDUCTEE_PAN)," +
                       "                  COMPANY_ID," +
                       "                  '" + TDSMAN.Classes.TDSMAN.T_pGroupId + "'," +
                       "                  EMPLOYEE_SERIAL_NO" +
                       "      FROM        " + TDSMAN.Classes.TDSMAN.T_tblTEMP_MST_DEDUCTEE + "";

                    if (dmlService.J_ExecSql(strSQL) == false)
                        return false;
                    //--
                    if (dmlService.J_IsDatabaseObjectExist(TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS, "EMPLOYEE_ID") == false)
                    {
                        if (J_Var.J_pDatabaseType == J_DatabaseType.SqlServer)
                            strSQL = "ALTER TABLE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + " ADD EMPLOYEE_ID MONEY DEFAULT 0";
                        else if (J_Var.J_pDatabaseType == J_DatabaseType.MsAccess)
                            strSQL = "ALTER TABLE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + " ADD COLUMN EMPLOYEE_ID NUMBER DEFAULT 0";
                        dmlService.J_ExecSql(strSQL);
                    }
                    //ADD EMPLOYEE_MASTER_ID IN " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DEDUCTEE_DETAILS + " FOR LINKING WITH EMPLOYEE MASTER

                    //FOR VALID PAN -- LINKING PAN WITH MASTER
                    strSQL = "UPDATE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + " " +
                      "         INNER JOIN MST_EMPLOYEE " +
                      "                 ON " + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + ".EMPLOYEE_PAN = MST_EMPLOYEE.EMPLOYEE_PAN  " +
                      "       SET    " + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + ".EMPLOYEE_ID     = MST_EMPLOYEE.EMPLOYEE_ID " +
                      "       WHERE  " + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + ".EMPLOYEE_PAN    <> 'PANNOTAVBL'" +
                      "       AND    MST_EMPLOYEE.COMPANY_ID             = " + CompanyId + " ";

                    if (dmlService.J_ExecSql(strSQL) == false)
                        return false;

                    // FOR PANNOTAVBL -- LINKING NAME WITH MASTER
                    strSQL = "UPDATE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + " " +
                      "         INNER JOIN MST_EMPLOYEE " +
                      "         ON " + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + ".EMPLOYEE_NAME = MST_EMPLOYEE.EMPLOYEE_NAME  " +
                      "  SET    " + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + ".EMPLOYEE_ID      = MST_EMPLOYEE.EMPLOYEE_ID " +
                      "  WHERE  " + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + ".EMPLOYEE_PAN     = 'PANNOTAVBL'" +
                      "  AND    MST_EMPLOYEE.EMPLOYEE_PAN            = 'PANNOTAVBL'" +
                      "  AND    MST_EMPLOYEE.COMPANY_ID              = " + CompanyId + " ";

                    if (dmlService.J_ExecSql(strSQL) == false)
                        return false;

                    // UPDATE CATEGORY
                    // FOR  PANNOTAVBL
                    strSQL = "UPDATE MST_EMPLOYEE " +
                      "         INNER JOIN " + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + " " +
                      "         ON " + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + ".EMPLOYEE_NAME = MST_EMPLOYEE.EMPLOYEE_NAME  " +
                      "  SET    MST_EMPLOYEE.CATEGORY                = " + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + ".CATEGORY " +
                      "  WHERE  " + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + ".EMPLOYEE_PAN     = 'PANNOTAVBL'" +
                      "  AND    MST_EMPLOYEE.EMPLOYEE_PAN            = 'PANNOTAVBL'" +
                      "  AND    MST_EMPLOYEE.COMPANY_ID              = " + CompanyId + " ";

                    if (dmlService.J_ExecSql(strSQL) == false)
                        return false;

                    // FOR  PANAVBL
                    strSQL = "UPDATE MST_EMPLOYEE " +
                      "         INNER JOIN " + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + " " +
                      "         ON " + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + ".EMPLOYEE_PAN  = MST_EMPLOYEE.EMPLOYEE_PAN  " +
                      "  SET    MST_EMPLOYEE.CATEGORY                = " + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + ".CATEGORY " +
                      "  WHERE  " + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + ".EMPLOYEE_PAN     <> 'PANNOTAVBL'" +
                      "  AND    MST_EMPLOYEE.EMPLOYEE_PAN            <> 'PANNOTAVBL'" +
                      "  AND    MST_EMPLOYEE.COMPANY_ID              = " + CompanyId + " ";

                    if (dmlService.J_ExecSql(strSQL) == false)
                        return false;
                    #endregion
                }
                else if (FormNo == T_FormNo.F24QForm16SalaryDetails)
                {
                    #region F24QSalaryDetailsForm16
                    //INSERTING NEW EMPLOYEES FOUND IN EXCEL TO THE MASTER
                    strSQL = "INSERT INTO MST_EMPLOYEE " +
