        #region lnkVerifyOnlyNewPANs_LinkClicked
        private void lnkVerifyOnlyNewPANs_LinkClicked(object sender, LinkLabelLinkClickedEventArgs e)
        {
            //--
            if (cmnService.J_ReturnInt32Value(lblNewDeducteesFound.Text) > 0)
            {
                //-- 2024/02/17
                if (cmnService.J_ReturnInt32Value(lblNewDeducteesFound.Text) > lngMAXLineNumbersPANVerificationMessage)
                {
                    if (cmnService.J_UserMessage(strMessagePANVerification, MessageBoxButtons.YesNo, MessageBoxIcon.Question, MessageBoxDefaultButton.Button2) == DialogResult.No)
                    {
                        BtnSave.Select();
                        return;
                    }
                }
                //-----------------------------------------------
                if (lngBasicInfoID == 0)
                {
                    string strForm = "";
                    if (cmbFormNo.Text == T_FormNo.F24QSalaryDetails)
                        strForm = T_FormNo.F24Q;
                    else
                        strForm = cmbFormNo.Text;
                    //
                    lngBasicInfoID = TdsMan.T_ReturnBasicInfoId(dmlService.J_pCommand, Convert.ToInt32(Support.GetItemData(cmbFinancialYear, cmbFinancialYear.SelectedIndex)),
                                        cmbQuarter.Text,
                                        Convert.ToInt32(Support.GetItemData(cmbCompany, cmbCompany.SelectedIndex)),
                                        strForm);
                    //    
                }
                //--
                TDSMAN.Classes.TDSMAN.T_pBasicInfoId = lngBasicInfoID;
                TDSMAN.Classes.TDSMAN.T_pQuarter = lblQtr.Text;
                TDSMAN.Classes.TDSMAN.T_pFormNo = lblFormNo.Tag.ToString();
                TDSMAN.Classes.TDSMAN.T_pTAN = lblTANNo.Text;
                TDSMAN.Classes.TDSMAN.T_FromModule = T_OTHERMODULENAME.IMPORT_EXCEL_REGULAR;
                TDSMAN.Classes.TDSMAN.T_ExcelImportFilePath = txtExcelPath.Text;
                //--
                this.Cursor = Cursors.WaitCursor;
                //--
                //TrnBulkPANNameValidation TrnBulkPANNameValidation = new TrnBulkPANNameValidation();
                //TrnBulkPANNameValidation.ShowDialog();
                if (TDSMAN.Classes.TDSMAN.T_SHOW_TRACES_ERR_MESSAGE == true)
                {
                    this.Cursor = Cursors.Default;
                    cmnService.J_UserMessage(TDSMAN.Classes.TDSMAN.T_SHOW_TRACES_ERR_MESSAGE_TEXT.ToString());
                    return;
                }
                //--
                TrnBulkPANNameValidationImprovedVersion_New TrnBulkPANNameValidationImprovedVersion = new TrnBulkPANNameValidationImprovedVersion_New();
                TrnBulkPANNameValidationImprovedVersion.ShowDialog();
                //--
                this.Cursor = Cursors.Default;

            }
            else
                cmnService.J_UserMessage("No records available");
        }
