        #region cmbCSVFormNo_SelectedIndexChanged
        private void cmbCSVFormNo_SelectedIndexChanged(object sender, EventArgs e)
        {
            pctVideoDemo.Visible = false;
            //
            chkCSVRoundOffTaxableAmount.Visible = false;
            if (cmbCSVFormNo.Text == T_FormNo.F24QForm16SalaryDetails || cmbCSVFormNo.Text == T_FormNo.F24QSalaryDetails)
            {
                chkEnterDeducteeDetailsOnly.Checked = false;
                chkEnterDeducteeDetailsOnly.Enabled = false;
                //
                lblNoteAdd.Visible = false;
                //
                if (cmbCSVFormNo.Text == T_FormNo.F24QForm16SalaryDetails)
                    pctVideoDemo.Visible = true;
                else
                    pctVideoDemo.Visible = false;
                //-- 2020/06/15
                if (cmbCSVFormNo.Text == T_FormNo.F24QSalaryDetails && TDSMAN.Classes.TDSMAN.T_EnableRoundOffTaxableAmt == true)
                    chkCSVRoundOffTaxableAmount.Visible = true;
                else
                    chkCSVRoundOffTaxableAmount.Visible = false;
                //--
                lblCSVChallanPathCaption.Visible = false;
                txtChallanCSVFilePath.Visible = false;
                btnSelectChallanCSVFile.Visible = false;
                lblCSVDeducteePathCaption.Text = "Salary Details CSV path";
                //--
                lblTaxComputingMessageF24QSDCSV.Visible = true; //-- 2025/01/21
            }
            else
            {
                pctVideoDemo.Visible = true;
                //
                lblNoteAdd.Visible = true;
                //
                if (chkEnterDeducteeDetailsOnly.Checked != true)
                {
                    chkEnterDeducteeDetailsOnly.Checked = false;
                    chkEnterDeducteeDetailsOnly.Enabled = true;
                }
                //--
                lblCSVChallanPathCaption.Visible = true;
                txtChallanCSVFilePath.Visible = true;
                btnSelectChallanCSVFile.Visible = true;
                lblCSVDeducteePathCaption.Text = "Deductee CSV file path";
                //--
                lblTaxComputingMessageF24QSDCSV.Visible = false; //-- 2025/01/21
            }
        }
